/*
 * A354681  Integers whose names in French contain no letter more than once.
 * https://oeis.org/A354681
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, fini, full, sign, word, less
 * Formula:   not stated
 * Range:     i8 n <= 25, i16 n <= 25, i32 n <= 25, i64 n <= 25, i128 n <= 25,
 *            big any n
 * Helpers:   add_letter
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Computes OEIS A354681: integers whose French name contains each
 * alphabetic letter at most once.  The sequence is generated by
 * testing successive integers starting from –4 and caching the
 * resulting values.  The implementation uses a bit‑mask to detect
 * duplicate letters; after adding a good number the candidate index
 * is advanced correctly, avoiding the earlier off‑by‑one error. */
#include <stdint.h>
#include <stdbool.h>
#include <ctype.h>
#include <stddef.h>
#include <stdlib.h>
#include "../utils/add_letter.h"

/* Basic word tables for numbers 0–999. */
static const char *unit_words[10] = {
    "zero", "un", "deux", "trois", "quatre",
    "cinq", "six", "sept", "huit", "neuf"
};
static const char *teens_words[10] = {
    "dix", "onze", "douze", "treize",
    "quatorze", "quinze", "seize",
    "dix-sept", "dix-huit", "dix-neuf"
};
static const char *tens_words[5] = { /* 20,30,40,50,60 */
    "vingt", "trente", "quarante", "cinquante", "soixante"
};

/* Add a word to the mask; returns false on duplicate letter. */
static bool add_word(const char *s, unsigned *mask)
{
    for (; *s; ++s) {
        if (!add_letter(*s, mask))
            return false;
    }
    return true;
}

/* Forward declaration. */
static bool add_number_word(uint64_t n, unsigned *mask);

/* Build the mask for the French representation of a non‑negative integer
 * 0 ≤ n < 1000.  Returns false if a duplicate letter is found.  For
 * numbers ≥ 1000 the function simply returns false (all such numbers
 * contain the word «mille», which has a repeated letter). */
static bool add_number_word(uint64_t n, unsigned *mask)
{
    if (n < 10)
        return add_word(unit_words[n], mask);

    if (n < 20)
        return add_word(teens_words[n - 10], mask);

    if (n < 100) {
        uint64_t tens = n / 10;
        uint64_t ones = n % 10;

        if (tens >= 2 && tens <= 6) {
            if (!add_word(tens_words[tens - 2], mask))
                return false;
            if (ones == 0)
                return true;
            if (ones == 1) {
                if (!add_word("et", mask))
                    return false;
                return add_word("un", mask);
            }
            return add_word(unit_words[ones], mask);
        }

        if (tens == 7) {          /* 70–79 */
            if (!add_word("soixante", mask))
                return false;
            uint64_t offset = n - 60;   /* 10–19 */
            if (offset == 10)    /* dix */
                return add_word("dix", mask);
            if (offset == 11)    /* onze */
                return add_word("et", mask) && add_word("onze", mask);
            return add_word(teens_words[offset - 10], mask);
        }

        if (tens == 8) {          /* 80–89 */
            if (!add_word("quatre", mask))
                return false;
            if (!add_word("vingt", mask))
                return false;
            if (ones == 0)
                return true;
            if (ones == 1)
                return add_word("et", mask) && add_word("un", mask);
            return add_word(unit_words[ones], mask);
        }

        if (tens == 9) {          /* 90–99 */
            if (!add_word("quatre", mask))
                return false;
            if (!add_word("vingt", mask))
                return false;
            uint64_t offset = n - 80;   /* 10–19 */
            if (offset == 10)
                return add_word("dix", mask);
            if (offset == 11)
                return add_word("et", mask) && add_word("onze", mask);
            return add_word(teens_words[offset - 10], mask);
        }
        return false;   /* should never reach here */
    }

    if (n < 1000) {
        uint64_t hundreds = n / 100;
        uint64_t rem = n % 100;
        if (hundreds == 1) {
            if (!add_word("cent", mask))
                return false;
        } else {
            if (!add_word(unit_words[hundreds], mask))
                return false;
            if (!add_word("cent", mask))
                return false;
        }
        if (rem > 0)
            return add_number_word(rem, mask);
        return true;
    }

    /* Numbers ≥ 1000 contain "mille", which has a repeated letter,
     * so they are automatically invalid. */
    return false;
}

/* Check whether a signed integer satisfies the unique‑letter condition. */
static bool good_integer(seq_t val)
{
    unsigned mask = 0;
    long long v = (long long)val;
    if (v < 0) {
        if (!add_word("moins", &mask))
            return false;
        v = -v;
    }
    if (v == 0)
        return add_word("zero", &mask);
    return add_number_word((uint64_t)v, &mask);
}

/* Cache parameters.  20000 entries are sufficient for n ≤ 10000. */
#define MAX_CACHE 20000
static seq_t cache[MAX_CACHE];
static size_t cache_len = 0;

/* Next candidate to test.  Starts at –4, the first element of the
 * sequence. */
static seq_t next_candidate = -4;

/* The requested sequence function. */
seq_t a(idx_t n)
{
    if (n == 0)
        return 0; /* undefined, but safe */

    /* Initialize cache with the first element if empty. */
    if (cache_len == 0) {
        cache[cache_len++] = next_candidate; /* -4 */
        next_candidate++;                    /* next candidate = -3 */
    }

    /* Grow the cache until the n‑th term is available. */
    while (cache_len < n) {
        while (true) {
            if (good_integer(next_candidate)) {
                if (cache_len < MAX_CACHE) {
                    cache[cache_len++] = next_candidate;
                } else {
                    /* Cache overflow – not expected for the bounds. */
                    abort();
                }
                next_candidate++;   /* advance to next candidate */
                break;
            }
            next_candidate++;
        }
    }

    return cache[n - 1];
}
